'use client';

import { useState, useOptimistic } from 'react';
import { useFormStatus } from 'react-dom';

interface Message { id: string; role: 'user' | 'assistant'; content: string; }

// Server Action defined on the server
import { sendMessage } from '@/lib/actions/chat';

export function ChatForm({
    messages,
    setMessages
}: { messages: Message[]; setMessages: React.Dispatch<React.SetStateAction<Message[]>> }) {
    const [optimisticMessages, addOptimistic] = useOptimistic(
        messages,
        (state: Message[], newMsg: Message) => [...state, newMsg]
    );

    const { pending } = useFormStatus();

    async function handleSubmit(formData: FormData) {
        const prompt = formData.get('prompt') as string;

        // Optimistically add user message
        addOptimistic({ id: 'temp', role: 'user', content: prompt });

        try {
            // Server Action streams the response
            const reader = await sendMessage(formData);

            // Stream tokens to UI
            const assistantMsg = { id: '', role: 'assistant', content: '' };
            setMessages(prev => [...prev, { ...assistantMsg, id: 'streaming' }]);

            for await (const chunk of reader) {
                setMessages(prev => prev.map(m =>
                    m.id === 'streaming' ? { ...m, content: m.content + chunk } : m
                ));
            }
        } catch (error) {
            addOptimistic({ id: 'error', role: 'assistant', content: 'Failed to get response' });
        }
    }

    return (
        <form action={handleSubmit}>
            <textarea name="prompt" placeholder="Ask about your codebase..." />
            <button type="submit" disabled={pending}>
                {pending ? 'Thinking...' : 'Send'}
            </button>
        </form>
    );
}

